<script setup lang="ts">
import type { EChartsCoreOption } from 'echarts/core'; import type { DailyActivity, DsaPerformance, ModuleBreakdown, ProgressOverview, ReviewPerformance } from '~/types/domain'; import { formatMinutes } from '~/utils/format'
definePageMeta({ layout: 'app' }); useSeoMeta({ title: 'Analytics' }); const api = useApi(); const active = ref('Overview'); const tabs = ['Overview','Activity','Review','DSA','Modules']; const loading = ref(true); const error = ref<unknown>(); const toDate = new Date(); const fromDate = new Date(); fromDate.setUTCDate(toDate.getUTCDate() - 29); const from = ref(fromDate.toISOString().slice(0,10)); const to = ref(toDate.toISOString().slice(0,10)); const overview = ref<ProgressOverview>(); const activity = ref<DailyActivity>(); const review = ref<ReviewPerformance>(); const dsa = ref<DsaPerformance>(); const modules = ref<ModuleBreakdown>()
async function load() { loading.value = true; error.value = undefined; const query = { fromUtc: new Date(`${from.value}T00:00:00Z`).toISOString(), toUtc: new Date(`${to.value}T23:59:59Z`).toISOString() }; try { [overview.value, activity.value, review.value, dsa.value, modules.value] = await Promise.all([api.get<ProgressOverview>('/analytics/progress-overview', query), api.get<DailyActivity>('/analytics/daily-activity', query), api.get<ReviewPerformance>('/analytics/review-performance', query), api.get<DsaPerformance>('/analytics/dsa-performance', query), api.get<ModuleBreakdown>('/analytics/module-breakdown', query)]) } catch (caught) { error.value = caught } finally { loading.value = false } }
const activityOption = computed<EChartsCoreOption>(() => ({ tooltip: { trigger: 'axis' }, xAxis: { type: 'category', data: activity.value?.days.map(day => day.date) ?? [] }, yAxis: { type: 'value', name: 'Minutes' }, series: [{ type: 'line', smooth: true, data: activity.value?.days.map(day => day.studyMinutes) ?? [], areaStyle: {}, color: '#4f46e5' }] })); const reviewOption = computed<EChartsCoreOption>(() => ({ tooltip: { trigger: 'item' }, series: [{ type: 'pie', radius: ['45%','70%'], data: review.value ? [{ name:'Again', value:review.value.againCount },{ name:'Hard', value:review.value.hardCount },{ name:'Good', value:review.value.goodCount },{ name:'Easy', value:review.value.easyCount }] : [] }] })); const dsaOption = computed<EChartsCoreOption>(() => ({ xAxis: { type:'category', data:['Solved','Partial','Failed','Skipped'] }, yAxis:{ type:'value' }, series:[{ type:'bar', data:dsa.value ? [dsa.value.solvedAttempts,dsa.value.partiallySolvedAttempts,dsa.value.failedAttempts,dsa.value.skippedAttempts] : [], color:'#06b6d4' }] })); const moduleOption = computed<EChartsCoreOption>(() => ({ tooltip:{ trigger:'item' }, series:[{ type:'pie', radius:'70%', data:modules.value?.modules.map(item => ({ name:item.resourceType, value:item.completedItems })) ?? [] }] })); watch([from,to], load); onMounted(load)
</script>
<template><div><CorePageHeader title="Analytics" description="Understand the evidence, then decide what to do next."><div class="dates"><input v-model="from" type="date" aria-label="From date"><span>to</span><input v-model="to" type="date" aria-label="To date"></div></CorePageHeader><nav class="tabs"><button v-for="tab in tabs" :key="tab" :class="{ active: active === tab }" @click="active = tab">{{ tab }}</button></nav><CoreLoadingState v-if="loading" label="Calculating analytics" /><CoreErrorState v-else-if="error" :error="error" @retry="load" /><template v-else><section v-if="active === 'Overview' && overview" class="overview"><article><span>Study time</span><strong>{{ formatMinutes(overview.studyMinutes) }}</strong></article><article><span>Active days</span><strong>{{ overview.activeStudyDays }}</strong></article><article><span>Reviews</span><strong>{{ overview.reviewsCompleted }}</strong></article><article><span>DSA attempts</span><strong>{{ overview.dsaAttempts }}</strong></article><article><span>Completed sessions</span><strong>{{ overview.completedSessions }}</strong></article><article><span>Study items</span><strong>{{ overview.studyItemsCompleted }}</strong></article></section><AnalyticsChartContainer v-else-if="active === 'Activity' && activity" title="Daily study activity" :summary="`${activity.days.filter(day => day.studyMinutes > 0).length} active days in this range.`" :metric="formatMinutes(activity.days.reduce((sum, day) => sum + day.studyMinutes, 0))" :option="activityOption"><table><thead><tr><th>Date</th><th>Minutes</th><th>Reviews</th><th>DSA</th></tr></thead><tbody><tr v-for="day in activity.days" :key="day.date"><td>{{ day.date }}</td><td>{{ day.studyMinutes }}</td><td>{{ day.reviews }}</td><td>{{ day.dsaAttempts }}</td></tr></tbody></table></AnalyticsChartContainer><AnalyticsChartContainer v-else-if="active === 'Review' && review" title="Review performance" :summary="`${review.successRate}% of reviews were Good or Easy.`" :metric="`${review.totalReviews} reviews`" :option="reviewOption"><p>Again {{ review.againCount }}, Hard {{ review.hardCount }}, Good {{ review.goodCount }}, Easy {{ review.easyCount }}</p></AnalyticsChartContainer><AnalyticsChartContainer v-else-if="active === 'DSA' && dsa" title="DSA performance" :summary="`${dsa.solvedRate}% solved rate across ${dsa.problemsPracticed} problems.`" :metric="`${dsa.totalAttempts} attempts`" :option="dsaOption"><p>Solved {{ dsa.solvedAttempts }}, partially solved {{ dsa.partiallySolvedAttempts }}, failed {{ dsa.failedAttempts }}, skipped {{ dsa.skippedAttempts }}</p></AnalyticsChartContainer><AnalyticsChartContainer v-else-if="active === 'Modules' && modules" title="Learning module mix" :summary="`${modules.totalCompletedItems} completed items distributed across learning modules.`" :metric="`${modules.modules.length} modules`" :option="moduleOption"><table><tbody><tr v-for="module in modules.modules" :key="module.resourceType"><td>{{ module.resourceType }}</td><td>{{ module.completedItems }}</td><td>{{ module.percentage }}%</td></tr></tbody></table></AnalyticsChartContainer><CoreEmptyState v-else title="No activity in this range" description="Complete reviews, attempts, or study sessions to populate this view." /></template></div></template>
<style scoped>.dates { display: flex; align-items: center; gap: .4rem; }.dates input { padding: .45rem; border: 1px solid var(--ui-border); border-radius: .45rem; }.tabs { display: flex; gap: .3rem; margin-bottom: 1rem; overflow-x: auto; border-bottom: 1px solid var(--ui-border); }.tabs button { padding: .65rem .85rem; color: var(--ui-text-muted); }.tabs button.active { color: var(--ui-primary); border-bottom: 2px solid var(--ui-primary); }.overview { display: grid; grid-template-columns: repeat(3,1fr); gap: .75rem; }.overview article { display: grid; gap: .4rem; padding: 1.25rem; border: 1px solid var(--ui-border); border-radius: .75rem; }.overview span { color: var(--ui-text-muted); }.overview strong { font-size: 1.7rem; }table { width: 100%; border-collapse: collapse; }th,td { padding: .4rem; text-align: left; border-bottom: 1px solid var(--ui-border); }@media(max-width:650px){.overview{grid-template-columns:repeat(2,1fr)}.dates{flex-wrap:wrap}}</style>
